// Starts the issuer API (default port 4001).
//
// SYNCSHIELD ADAPTATION: paths, port and the admin token come from the environment so that several
// instances (and the automated tests) never share state, and so the issuer key is never regenerated by accident.
//   TRUE_DATA_DIR            private files: issuer.db, issuer-key.json   (default: services/issuer-api/data)
//   TRUE_REGISTRY_FILE       public key registry (stand-in registry used by the original verifier)
//   ISSUER_PUBLIC_JWK_FILE   where to write the PUBLIC key to be pinned by regional verifiers
//   ISSUER_PORT              default 4001
//   ISSUER_ADMIN_TOKEN       required when SYNCSHIELD=1 (admin routes fail closed without it)
import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { serve } from '@hono/node-server';
import { ISSUER_ID, ISSUER_NAME } from '@true/shared';
import { generateSigningKeyPair } from '@true/credentials';
import { openIssuerDb } from './db.ts';
import { createIssuerApp, type IssuerKeys } from './app.ts';

const env = process.env;
const DATA_DIR = env.TRUE_DATA_DIR ? pathToFileURL(resolve(env.TRUE_DATA_DIR) + '/') : new URL('../data/', import.meta.url);
const REGISTRY_FILE = env.TRUE_REGISTRY_FILE
  ? pathToFileURL(resolve(env.TRUE_REGISTRY_FILE))
  : new URL('../../../data/registry.json', import.meta.url);
const PORT = Number(env.ISSUER_PORT ?? 4001);
const SYNCSHIELD = env.SYNCSHIELD === '1';
const ADMIN_TOKEN = env.ISSUER_ADMIN_TOKEN;

if (SYNCSHIELD && !ADMIN_TOKEN) {
  console.error('SYNCSHIELD=1 requires ISSUER_ADMIN_TOKEN: refusing to start with open admin routes.');
  process.exit(1);
}

mkdirSync(DATA_DIR, { recursive: true });
mkdirSync(new URL('./', REGISTRY_FILE), { recursive: true });

// Load the issuer signing key, or create it on first run. It is never regenerated if the file exists.
const keyFile = new URL('issuer-key.json', DATA_DIR);
let keys: IssuerKeys;
if (existsSync(keyFile)) {
  keys = JSON.parse(readFileSync(keyFile, 'utf8'));
} else {
  keys = await generateSigningKeyPair();
  writeFileSync(keyFile, JSON.stringify(keys, null, 2), { mode: 0o600 });
  try { chmodSync(keyFile, 0o600); } catch { /* best effort on Windows */ }
}

// Publish the PUBLIC key to the registry so verifiers can check signatures without calling us.
const registry = existsSync(REGISTRY_FILE) ? JSON.parse(readFileSync(REGISTRY_FILE, 'utf8')) : { issuers: {} };
registry.issuers[ISSUER_ID] = { name: ISSUER_NAME, publicJwk: keys.publicJwk };
writeFileSync(REGISTRY_FILE, JSON.stringify(registry, null, 2));

// Optional: the pinned-public-key file regional verifiers are configured with.
if (env.ISSUER_PUBLIC_JWK_FILE) {
  mkdirSync(dirname(resolve(env.ISSUER_PUBLIC_JWK_FILE)), { recursive: true });
  writeFileSync(env.ISSUER_PUBLIC_JWK_FILE, JSON.stringify({ issuerId: ISSUER_ID, publicJwk: keys.publicJwk }, null, 2));
}

const db = openIssuerDb(fileURLToPath(new URL('issuer.db', DATA_DIR)));
const app = createIssuerApp(db, keys, SYNCSHIELD || ADMIN_TOKEN ? { adminToken: ADMIN_TOKEN ?? '' } : {});

serve({ fetch: app.fetch, port: PORT, hostname: '127.0.0.1' }, () =>
  console.log(`Issuer API listening on http://127.0.0.1:${PORT}${SYNCSHIELD ? ' (SyncShield mode, admin token required)' : ''}`));
